class Solution {
  private static final long NEG = Long.MIN_VALUE / 4;
  private long value;
  private int count;

  private static boolean better(long v1, int c1, long v2, int c2) {
    return v1 > v2 || (v1 == v2 && c1 < c2);
  }

  // best (sum - lambda * count) over selections with at least one subarray; ties prefer fewer
  // subarrays
  private void solve(long[] pre, int n, int l, int r, long lambda) {
    long[] someVal = new long[n + 1], baseKey = new long[n + 1];
    int[] someCnt = new int[n + 1], baseCnt = new int[n + 1];
    int[] dq = new int[n + 2];
    int head = 0, tail = 0;
    someVal[0] = NEG;
    for (int i = 0; i <= n; i++) {
      int add = i - l;
      if (add >= 0) {
        while (tail > head
            && (baseKey[add] > baseKey[dq[tail - 1]]
                || (baseKey[add] == baseKey[dq[tail - 1]]
                    && baseCnt[add] <= baseCnt[dq[tail - 1]]))) tail--;
        dq[tail++] = add;
      }
      while (tail > head && dq[head] < i - r) head++;
      if (i > 0) {
        someVal[i] = someVal[i - 1];
        someCnt[i] = someCnt[i - 1];
        if (tail > head) {
          int t = dq[head];
          long cand = baseKey[t] + pre[i] - lambda;
          int cc = baseCnt[t] + 1;
          if (someVal[i] == NEG || better(cand, cc, someVal[i], someCnt[i])) {
            someVal[i] = cand;
            someCnt[i] = cc;
          }
        }
      }
      long bestVal = 0;
      int bestCnt = 0;
      if (i > 0 && someVal[i] != NEG && better(someVal[i], someCnt[i], 0, 0)) {
        bestVal = someVal[i];
        bestCnt = someCnt[i];
      }
      baseKey[i] = bestVal - pre[i];
      baseCnt[i] = bestCnt;
    }
    value = someVal[n];
    count = someCnt[n];
  }

  public long maximumSum(int[] nums, int m, int l, int r) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    solve(pre, n, l, r, 0);
    if (count <= m) return value;
    long lo = 0, hi = 2_000_000_000_000L;
    while (lo < hi) {
      long mid = (lo + hi) >>> 1;
      solve(pre, n, l, r, mid);
      if (count <= m) hi = mid;
      else lo = mid + 1;
    }
    solve(pre, n, l, r, lo);
    return value + lo * m;
  }
}
